('haidushki-vodopadi-berkovica', 'detailed', 'Хайдушки водопади (Берковица)', 'Западна Стара планина', 'Идея', 'Лесна', NULL, NULL, NULL, '', '', '', '', 'Пролет – Есен; подходящ и за семейни разходки', 'https://www.google.com/search?q=prognoza+Berkovitsa+Haidushki+vodopadi', '', '', '', 'Берковица → изоставен завод Ком / начало на екопътеката → Хайдушки водопади; алтернативно достъп с по-проходим автомобил почти до водопадите.', 'ДОБРО — потвърдено е началото в западните покрайнини на Берковица, достъпът с автомобил и леката семейна трудност.', '{"summary":"Най-удобно е с кола до края на Берковица; обществен транспорт и таксита не са потвърдени.","car":{"available":true,"text":"До началото се стига от центъра на Берковица по кафевите указателни стрелки; може да се паркира при изоставения завод Ком.","parkingNote":"GPS паркинг не е потвърден; при по-проходим автомобил може да се стигне почти до водопадите."},"public":{"steps":[]}}'::jsonb, '[{"name":"хижа Ком","elevation":1620,"beds":22,"officialPhone":"0889 681 693","altPhone":"0889 681 693","email":null,"gps":"43.188450, 23.081283","verified":true,"conflict":"Контактът е потвърден в два източника за старата хижа Ком; втори независим номер за същия обект не беше намерен в наличните резултати."}]'::jsonb, '{"level":"НИСЪК","color":"emerald","points":["Екопътеката е лека и подходяща за деца.","Има малък технически участък само в края при слизането до водопадите.","Маркировката е рядка, но ориентирането е сравнително лесно по пътя."],"conclusion":"Лек и семеен маршрут с минимални технически трудности."}'::jsonb, '[{"date":null,"label":"Берковица → Хайдушки водопади","type":"Преход","distance":"неизвестно","gain":"неизвестно","time":"1-2 ч","stay":null,"difficulty":"Лесна"}]'::jsonb, '[{"name":"Хижа Ком","location":"Берковска планина","rating":null,"price":null,"note":"Подходяща база за по-дълъг престой в района."}]'::jsonb, '[]'::jsonb, 'https://embed.windy.com/embed.html?type=map&location=coordinates&metricRain=mm&metricWind=km%2Fh&zoom=10&overlay=rain&product=ecmwf&level=surface&lat=43.188450&lon=23.081283', ''),
('zavala-kitka', 'detailed', 'Завала – Китка', 'Завалска планина', 'Идея', 'Лесна', 4.5, 203, 203, '', '', '', '', 'Пролет – Есен; възможно целогодишно при сухо време', 'https://www.google.com/search?q=prognoza+Zavala+Kitka', '', '', '', 'с. Завала → черен път → ферма / овчарник → връх Китка; алтернативно двудневно комбиниране със с. Неделково.', 'ДОБРО — потвърден кратък маршрут, с координати, дистанция и денивелация от допълнителен източник.', '{"summary":"Най-лесно е с кола до центъра на с. Завала; обществен транспорт и таксита не са потвърдени.","car":{"available":true,"text":"Автомобил може да се остави в центъра на селото или при новоизградения овчарник по черния път.","parkingNote":"Точен GPS паркинг не е потвърден, но са налични начални координати за селото."},"public":{"steps":[]}}'::jsonb, '[]'::jsonb, '{"level":"НИСЪК","color":"emerald","points":["Маршрутът е кратък и сравнително равномерен.","Последният участък към върха е стръмен, но къс.","Възможно е да се комбинира с друг маршрут в Завалска планина."],"conclusion":"Лесен и бърз маршрут, подходящ и при ограничено време."}'::jsonb, '[{"date":null,"label":"с. Завала → връх Китка","type":"Преход","distance":"4.5 км","gain":"203 м","time":"1.5 ч","stay":null,"difficulty":"Лесна"}]'::jsonb, '[]'::jsonb, '[]'::jsonb, '', '')
